fn solve(r1: i8, c1: i8, r2: i8, c2: i8) -> Vec<i8> {
    // Rook moves
    // 0 if same square, 1 if same row or column, otherwise 2
    let rook = if r1 == r2 && c1 == c2 {
        0
    } else if r1 == r2 || c1 == c2 {
        1
    } else {
        2
    };

    // Bishop moves
    // 0 if same square OR unreachable (different color),
    // 1 if on the same diagonal,
    // 2 if same color but not on the same diagonal
    let bishop = if r1 == r2 && c1 == c2 {
        0
    } else {
        // squares have the same color if the sum of coordinates mod 2 are equal
        let same_color = (r1 + c1) % 2 == (r2 + c2) % 2;
        if !same_color {
            0
        } else if (r1 - r2).abs() == (c1 - c2).abs() {
            1
        } else {
            2
        }
    };

    // King moves = Chebyshev distance
    let king = std::cmp::max((r1 - r2).abs(), (c1 - c2).abs());

    vec![rook, bishop, king]
}

